import { assignDrawPosition } from '../matchUps/drawPositions/drawPositionPlacement.mjs';
import { getStageEntries } from '../../query/drawDefinition/stageGetter.mjs';
import { getParticipantId } from '../../functions/global/extractors.mjs';
import { shuffleArray } from '../../tools/arrays.mjs';
import { numericSort } from '../../tools/sorting.mjs';
import { STRUCTURE_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';
import { DIRECT_ENTRY_STATUSES } from '../../constants/entryStatusConstants.mjs';
import { MAIN } from '../../constants/drawDefinitionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function positionPagePlayoff({ tournamentRecord, drawDefinition, seedsOnly, random, event, }) {
    const mainStructures = drawDefinition.structures?.filter(({ stage }) => stage === MAIN) ?? [];
    const qualifierOne = mainStructures.find(({ stageSequence }) => stageSequence === 1);
    const eliminator = mainStructures.find(({ stageSequence }) => stageSequence === 2);
    if (!qualifierOne || !eliminator)
        return { error: STRUCTURE_NOT_FOUND };
    const entries = getStageEntries({ entryStatuses: DIRECT_ENTRY_STATUSES, drawDefinition, stage: MAIN });
    const enteredIds = entries.map(getParticipantId);
    const seededIds = (qualifierOne.seedAssignments ?? [])
        .filter(({ participantId }) => participantId && enteredIds.includes(participantId))
        .sort((a, b) => numericSort(a.seedNumber, b.seedNumber))
        .map(getParticipantId)
        .slice(0, 2);
    const unseededIds = seedsOnly
        ? []
        : shuffleArray(enteredIds.filter((id) => !seededIds.includes(id)), random);
    const orderedIds = [...seededIds, ...unseededIds];
    const placements = [
        { structureId: qualifierOne.structureId, participantIds: orderedIds.slice(0, 2) },
        { structureId: eliminator.structureId, participantIds: orderedIds.slice(2, 4) },
    ];
    for (const { structureId, participantIds } of placements) {
        for (const [index, participantId] of participantIds.entries()) {
            const result = assignDrawPosition({
                drawPosition: index + 1,
                tournamentRecord,
                drawDefinition,
                participantId,
                structureId,
                event,
            });
            if (result.error)
                return result;
        }
    }
    return { ...SUCCESS };
}

export { positionPagePlayoff };
