import { SINGLES, DOUBLES, TEAM, HYBRID } from '../../constants/eventConstants.mjs';
import { DIRECT_ACCEPTANCE } from '../../constants/entryStatusValues.mjs';
import { MAIN } from '../../constants/drawDefinitionConstants.mjs';
import { UUID } from '../../tools/UUID.mjs';

